const statusLabels: Record<RequestStatus, string> = requestStatusNames
const eventLabels = { SUBMITTED:'Обращение отправлено', RETURNED:'Возвращено на доработку', CHANGED:'Действующие условия изменены', STAGE_APPROVED:'Этап согласован', EXPIRED:'Срок истёк', INVALID:'Условия изменились', CREATED: 'Заявка отправлена', EDITED: 'Заявка изменена', APPROVED: 'Заявка одобрена', REJECTED: 'Заявка отклонена', CANCELLED: 'Заявка отменена' } as const
const sizeLabel = (size: number) => size < 1024 * 1024 ? `${Math.ceil(size / 1024)} КБ` : `${(size / 1024 / 1024).toFixed(1)} МБ`
const shiftWindow = (start: string, end: string, timezone: string) => {
  const startDate = zonedDateAndTime(start, timezone).date
  const endDate = zonedDateAndTime(end, timezone).date
  return `${displayDate(startDate)} · ${formatTime(start, timezone)} — ${startDate === endDate ? '' : `${displayDate(endDate)} · `}${formatTime(end, timezone)}`
}
const requestStatusLabel = (request: StaffRequest) => request.processLabel ?? processLabel(request)
const absenceReasonLabels = { SICK: 'Болезнь', PERSONAL: 'Личные обстоятельства', OTHER: 'Другое' } as const
const periodLabel = (request: Pick<StaffRequest, 'startDate' | 'endDate'>) => request.startDate ? request.endDate && request.endDate !== request.startDate ? `${displayDate(request.startDate)} — ${displayDate(request.endDate)}` : displayDate(request.startDate) : 'Без даты'


function RequestCard({ request, incoming, timezone, onOpen }: { request: StaffRequest; incoming: boolean; timezone: string; onOpen: () => void }) {
  const unread = incoming && request.status === 'PENDING' && !request.readByViewer
  const shift = ['SHIFT_CHANGE', 'SHIFT_PROPOSAL'].includes(request.systemCodeSnapshot ?? '')
  const original = request.originalStartAt && request.originalEndAt ? shiftWindow(request.originalStartAt, request.originalEndAt, timezone) : 'Исходная смена не указана'
  const proposed = request.proposedStartAt && request.proposedEndAt ? shiftWindow(request.proposedStartAt, request.proposedEndAt, timezone) : 'Новое время не указано'
  return <div className="request-table-item"><ActionSurface type="button" className={`request-card request-row${unread ? ' request-card--unread' : ''}`} onClick={onOpen} aria-label={`${request.creatorName}, ${request.typeNameSnapshot}, ${requestStatusLabel(request)}`}>
    <span className="request-row__person"><MemberAvatar memberId={request.createdByMemberId} locationId={request.locationId} url={request.creatorAvatarUrl} name={request.creatorName} className="app-avatar" /><span><strong><MemberProfileLink memberId={request.createdByMemberId} locationId={request.locationId}>{request.creatorName}</MemberProfileLink></strong><small>{request.creatorEmail}</small></span>{unread && <i className="request-unread" aria-label="Не прочитана" />}</span>
    <span className="request-row__type"><span className="request-type-label">{request.typeNameSnapshot}</span><small className="location-badge" data-tone={locationTone(request.locationId ?? '')}>⌖ {request.locationName}</small>{request.staffingPositionName && <small>{request.staffingPositionName}</small>}</span>
    <span className="request-row__period"><strong>{shift ? proposed : periodLabel(request)}</strong>{request.systemCodeSnapshot === 'SHIFT_CHANGE' && <small>Исходная: {original}</small>}{request.systemCodeSnapshot === 'DAY_OFF' && request.relatedShiftId && <small>Смена: {original}</small>}{request.comment && <small className="request-card__comment">{request.comment}</small>}</span>
    <span className="request-row__duration">{request.startDate ? `${absenceDays(request.startDate, request.endDate ?? request.startDate)} дн.` : '—'}</span>
    <span className={`request-status request-status--${request.status.toLowerCase()}`}>{requestStatusLabel(request)}</span>
    <time dateTime={request.createdAt}>{new Date(request.createdAt).toLocaleDateString('ru-RU')}</time>
  </ActionSurface><DocumentActionsMenu label={`Действия заявки ${request.typeNameSnapshot}`}><button onClick={onOpen}><RequestIcon code={request.systemCodeSnapshot} />Открыть заявку</button></DocumentActionsMenu></div>
}

export function RequestForm({ organization, request, initialShiftId, initialProposal = false, initialProposalDate, initialSystemCode, onClose }: { organization: OrganizationSummary; request?: StaffRequest | null; initialShiftId?: string; initialProposal?: boolean; initialProposalDate?: string; initialSystemCode?: RequestSystemCode; onClose: () => void }) {
  const toast = useToast()
  const { apiRequest, uploadFile } = useAuth()
  const queryClient = useQueryClient()
  const typeQuery = useRequestTypes(organization.id,!!request)
  const types = useMemo(() => {
    const available = [...(typeQuery.data?.types ?? [])]
    if (request && !available.some(type => type.id === request.requestTypeId)) available.push({ id: request.requestTypeId, name: request.typeNameSnapshot, description: null, systemCode: request.systemCodeSnapshot, dateMode: request.formSnapshot?.dateMode ?? 'NONE', requiresComment: request.formSnapshot?.requiresComment ?? false, allowsAttachments: request.formSnapshot?.allowsAttachments ?? false, definition: request.formSnapshot, isActive: false })
    return available.filter(type => (type.isActive || type.id === request?.requestTypeId) && type.systemCode !== 'STAFFING_RESPONSE' && (type.systemCode !== 'STAFFING' || canAccess(organization, 'staffing.create')))
  }, [typeQuery.data, organization, request])
  const planning = useSchedulePlanning(organization.id)
  const positions = planning.data?.positions.filter(position => position.isActive) ?? []
  const [choosingType, setChoosingType] = useState(!request && !initialSystemCode && !initialShiftId && !initialProposal)
  const [staffingPositionId, setStaffingPositionId] = useState('')
  const [staffingPositionName, setStaffingPositionName] = useState('')
  const shifts = useMyUpcomingShifts(organization.id)
  const [typeId, setTypeId] = useState(request ? request.requestTypeId : types.find(type => type.systemCode === (initialSystemCode ?? (initialShiftId ? 'SHIFT_CHANGE' : initialProposal ? 'SHIFT_PROPOSAL' : '')))?.id ?? types[0]?.id ?? '')
  const [startDate, setStartDate] = useState(request?.startDate ?? '')
  const [endDate, setEndDate] = useState(request?.endDate ?? '')
  const [absenceReason, setAbsenceReason] = useState(request?.absenceReason ?? 'SICK')
  const [comment, setComment] = useState(request?.comment ?? '')
  const [shiftId, setShiftId] = useState(request?.relatedShiftId ?? initialShiftId ?? '')
  const [proposedStartDate, setProposedStartDate] = useState(request?.proposedStartAt ? zonedDateAndTime(request.proposedStartAt, organization.timezone).date : initialProposal || initialSystemCode === 'STAFFING' ? initialProposalDate ?? '' : '')
  const [proposedStartTime, setProposedStartTime] = useState(request?.proposedStartAt ? zonedDateAndTime(request.proposedStartAt, organization.timezone).time : initialProposal || initialSystemCode === 'STAFFING' ? '09:00' : '')
  const [proposedEndDate, setProposedEndDate] = useState(request?.proposedEndAt ? zonedDateAndTime(request.proposedEndAt, organization.timezone).date : initialProposal || initialSystemCode === 'STAFFING' ? initialProposalDate ?? '' : '')
  const [proposedEndTime, setProposedEndTime] = useState(request?.proposedEndAt ? zonedDateAndTime(request.proposedEndAt, organization.timezone).time : initialProposal || initialSystemCode === 'STAFFING' ? '18:00' : '')
  const [files, setFiles] = useState<File[]>([])
  const [answers,setAnswers]=useState<RequestAnswers>(request?.answers??{})
  const [savedId,setSavedId]=useState(request?.id??'')
  const [submissionKey]=useState(()=>crypto.randomUUID())
  const [subjectMemberId,setSubjectMemberId]=useState('')
  const directory=useOrganizationDirectory(organization.id,canAccess(organization,'requests.onBehalf'))
  const [uploaded,setUploaded]=useState<string[]>([])
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  useToastFeedback('', error)
  const selectedType = types.find((item) => item.id === typeId)
  const type = selectedType&&request?.requestTypeId===selectedType.id?{...selectedType,dateMode:request.formSnapshot?.dateMode??selectedType.dateMode,requiresComment:request.formSnapshot?.requiresComment??selectedType.requiresComment,allowsAttachments:request.formSnapshot?.allowsAttachments??selectedType.allowsAttachments}:selectedType
  useEffect(() => {
    if (!typeId && types.length) setTypeId(types.find(type => type.systemCode === (initialSystemCode ?? (initialShiftId ? 'SHIFT_CHANGE' : initialProposal ? 'SHIFT_PROPOSAL' : '')))?.id ?? types[0].id)
  }, [types, typeId, initialShiftId, initialProposal, initialSystemCode])
  const selectedShift = shifts.data?.shifts.find((item) => item.id === shiftId)
  function chooseShift(id: string) {
    setShiftId(id)
    const shift = shifts.data?.shifts.find((item) => item.id === id)
    const start = shift ? zonedDateAndTime(shift.scheduledStartAt, organization.timezone) : null
    const end = shift ? zonedDateAndTime(shift.scheduledEndAt, organization.timezone) : null
    if (type?.systemCode === 'DAY_OFF') { setStartDate(start?.date ?? ''); setEndDate(start?.date ?? '') }
    setProposedStartDate(start?.date ?? ''); setProposedStartTime(start?.time ?? '')
    setProposedEndDate(end?.date ?? ''); setProposedEndTime(end?.time ?? '')
  }
  useEffect(() => {
    if (initialShiftId && !request && !proposedStartDate && shifts.data?.shifts.some(shift => shift.id === initialShiftId)) {
      const shift = shifts.data.shifts.find(item => item.id === initialShiftId)!
      const start = zonedDateAndTime(shift.scheduledStartAt, organization.timezone)
      const end = zonedDateAndTime(shift.scheduledEndAt, organization.timezone)
      if (initialSystemCode === 'DAY_OFF') { setStartDate(start.date); setEndDate(start.date) }
      setProposedStartDate(start.date); setProposedStartTime(start.time); setProposedEndDate(end.date); setProposedEndTime(end.time)
    }
  }, [initialShiftId, shifts.data, request, proposedStartDate, organization.timezone, initialSystemCode])
  async function submit(event: FormEvent) {
    event.preventDefault(); if (!type) return; setBusy(true); setError('')
    try {
      if (['SHIFT_CHANGE', 'SHIFT_PROPOSAL', 'STAFFING'].includes(type.systemCode ?? '') && Date.parse(`${proposedEndDate}T${proposedEndTime}:00Z`) <= Date.parse(`${proposedStartDate}T${proposedStartTime}:00Z`)) throw new Error('Окончание смены должно быть позже начала.')
      if (files.length + (request?.attachments.length ?? 0) > 5) throw new Error('К заявке можно добавить не больше пяти файлов.')
      if (files.some((file) => file.size > 10 * 1024 * 1024)) throw new Error('Каждый файл должен весить не больше 10 МБ.')
      const result = await apiRequest<RequestMutationResponse>(`/organizations/${organization.id}/requests${savedId ? `/${savedId}` : ''}`, { method: savedId ? 'PATCH' : 'POST', body: { draft:type.systemCode!=='SICK',submissionKey,answers,subjectMemberId:subjectMemberId||undefined, ...(type.systemCode === 'STAFFING' ? { staffingPositionId: staffingPositionId || null, staffingPositionName: staffingPositionId ? null : staffingPositionName } : {}), requestTypeId: typeId, startDate: startDate || null, endDate: endDate || null, comment: comment || null, absenceReason: type.systemCode === 'SICK' ? absenceReason : null, relatedShiftId: ['SHIFT_CHANGE', 'DAY_OFF'].includes(type.systemCode ?? '') ? shiftId || null : null, proposedStartDate: ['SHIFT_CHANGE', 'SHIFT_PROPOSAL', 'STAFFING'].includes(type.systemCode ?? '') ? proposedStartDate : null, proposedStartTime: ['SHIFT_CHANGE', 'SHIFT_PROPOSAL', 'STAFFING'].includes(type.systemCode ?? '') ? proposedStartTime : null, proposedEndDate: ['SHIFT_CHANGE', 'SHIFT_PROPOSAL', 'STAFFING'].includes(type.systemCode ?? '') ? proposedEndDate : null, proposedEndTime: ['SHIFT_CHANGE', 'SHIFT_PROPOSAL', 'STAFFING'].includes(type.systemCode ?? '') ? proposedEndTime : null } })
      setSavedId(result.request.id)
      for (const file of files){const key=file.name+':'+file.size+':'+file.lastModified;if(uploaded.includes(key))continue;await uploadFile(`/organizations/${organization.id}/requests/${result.request.id}/attachments`, file);setUploaded(current=>[...current,key])}
      if(type.systemCode!=='SICK')await apiRequest(`/organizations/${organization.id}/requests/${result.request.id}/submit`,{method:'POST',body:{}})
      await invalidateOrganizationWork(queryClient, organization.id)
      toast(type.systemCode === 'SICK' ? request ? 'Сообщение обновлено' : 'Отсутствие зарегистрировано' : request ? 'Заявка обновлена' : 'Заявка отправлена', 'success')
      onClose()
    } catch (failure) { setError(failure instanceof Error ? failure.message : 'Не удалось отправить заявку.') }
    finally { setBusy(false) }
  }
  if(!request&&!typeQuery.isLoading&&!typeQuery.isError&&(initialSystemCode||initialProposal||initialShiftId)&&!types.some(t=>t.systemCode===(initialSystemCode??(initialShiftId?'SHIFT_CHANGE':'SHIFT_PROPOSAL'))))return <DocumentDialog title="Действие недоступно" onClose={onClose}><p>Новая подача этого типа отключена в настройках. Действующие записи и история сохранены.</p></DocumentDialog>
  if (choosingType) return <RequestTypeChooser types={types} loading={typeQuery.isLoading} error={typeQuery.isError} retry={typeQuery.refetch} onClose={onClose} onSelect={item => { setTypeId(item.id); setStartDate(''); setEndDate(''); chooseShift(''); setChoosingType(false) }} />
  return <DocumentDialog key="request-form" className="request-form-dialog" eyebrow="Заявки" busy={busy} onClose={onClose} title={type?.systemCode === 'SICK' ? request ? 'Изменить сообщение' : 'Сообщить об отсутствии' : request ? 'Редактировать заявку' : 'Создать заявку'}><form onSubmit={submit}>{typeQuery.isLoading ? <p className="app-state"><span className="app-spinner" />Загружаем типы заявок…</p> : typeQuery.isError ? <div className="app-state"><p>Не удалось загрузить типы заявок.</p><button type="button" className="app-secondary" onClick={() => void typeQuery.refetch()}>Повторить</button></div> : null}<div className="request-form-purpose"><RequestIcon code={type?.systemCode} /><span><strong>{type?.name}</strong>{type?.description && <small>{type.description}</small>}</span></div>{!request&&canAccess(organization,'requests.onBehalf')&&(!type?.systemCode||type.systemCode==='VACATION')&&<EmployeePicker label="Оформить для сотрудника" emptyLabel="Для себя" required={false} value={subjectMemberId} onChange={setSubjectMemberId} members={directory.data?.members ?? []}/>}<WorkflowFields organizationId={organization.id} definition={request?.formSnapshot??type?.definition} answers={answers} onChange={setAnswers}/>{type?.systemCode === 'SICK' && <label><span>Причина отсутствия</span><Select value={absenceReason} onChange={event => setAbsenceReason(event.target.value as typeof absenceReason)}>{Object.entries(absenceReasonLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select></label>}{type?.dateMode !== 'NONE' && <div className="request-date-fields"><label><span>{type?.dateMode === 'SINGLE' ? type.systemCode === 'DAY_OFF' ? 'Дата отгула' : 'Дата события' : 'Первый день'}</span><DatePicker value={startDate} onChange={(event) => { setStartDate(event.target.value); if (type?.systemCode === 'DAY_OFF' && selectedShift && zonedDateAndTime(selectedShift.scheduledStartAt, organization.timezone).date !== event.target.value) setShiftId('') }} required /></label>{type?.dateMode === 'RANGE' && <label><span>Последний день</span><DatePicker min={startDate} value={endDate} onChange={(event) => setEndDate(event.target.value)} required /></label>}</div>}{type?.systemCode==='VACATION'&&<VacationWarning organizationId={organization.id} startDate={startDate} endDate={endDate} memberId={subjectMemberId||undefined}/>} {type?.systemCode==='VACATION'&&startDate&&endDate&&<p className="absence-note">Дней отпуска без федеральных праздников: {vacationDays(startDate,endDate)}. Один из периодов за рабочий год должен составлять не менее 14 дней. Кадровые документы оформляются вне сайта.</p>}{startDate && type?.dateMode !== 'NONE' && type?.systemCode!=='VACATION' && <p className="absence-note">Календарных дней: {absenceDays(startDate, type?.dateMode === 'SINGLE' ? startDate : endDate || startDate)}</p>}{['SHIFT_CHANGE', 'DAY_OFF'].includes(type?.systemCode ?? '') && <label><span>{type?.systemCode === 'DAY_OFF' ? 'Смена для отгула (необязательно)' : 'Текущая смена'}</span><Select value={shiftId} onChange={(event) => chooseShift(event.target.value)} required={type?.systemCode === 'SHIFT_CHANGE'}><option value="">Выберите свою смену</option>{shifts.data?.shifts.filter((shift) => new Date(shift.scheduledStartAt).getTime() > Date.now()).map((shift) => <option value={shift.id} key={shift.id}>{displayDate(zonedDateAndTime(shift.scheduledStartAt, organization.timezone).date)} · {formatTime(shift.scheduledStartAt, organization.timezone)}–{formatTime(shift.scheduledEndAt, organization.timezone)}</option>)}</Select></label>}{(type?.systemCode === 'STAFFING' || type?.systemCode === 'SHIFT_PROPOSAL' || (type?.systemCode === 'SHIFT_CHANGE' && selectedShift)) && <div className="request-shift-proposal"><p>{selectedShift ? <>Текущая смена: {shiftWindow(selectedShift.scheduledStartAt, selectedShift.scheduledEndAt, organization.timezone)} → предлагаемое изменение</> : type?.systemCode === 'STAFFING' ? <>Подмена в точке «{organization.location?.name}». Смену получит сотрудник после подтверждения отклика.</> : <>Предлагаемая новая смена. Она появится в расписании после одобрения.</>}</p><div><fieldset><legend>Предлагаемое начало</legend><label><span>Дата</span><DatePicker value={proposedStartDate} onChange={(event) => setProposedStartDate(event.target.value)} required /></label><label><span>Время</span><TimeInput value={proposedStartTime} onChange={(event) => setProposedStartTime(event.target.value)} required /></label></fieldset><fieldset><legend>Предлагаемое окончание</legend><label><span>Дата</span><DatePicker min={proposedStartDate} value={proposedEndDate} onChange={(event) => setProposedEndDate(event.target.value)} required /></label><label><span>Время</span><TimeInput value={proposedEndTime} onChange={(event) => setProposedEndTime(event.target.value)} required /></label></fieldset></div></div>}{type?.systemCode === 'STAFFING' && <label><span>Кто нужен на смену</span>{positions.length ? <Select required value={staffingPositionId} onChange={event => setStaffingPositionId(event.target.value)}><option value="">Выберите должность</option>{positions.map(position => <option key={position.id} value={position.id}>{position.name}</option>)}</Select> : <input required minLength={2} maxLength={120} value={staffingPositionName} onChange={event => setStaffingPositionName(event.target.value)} placeholder="Например, бариста" />}</label>}<label><span>Комментарий{type?.requiresComment ? ' *' : ''}</span><textarea rows={3} maxLength={type?.systemCode === 'SICK' ? 500 : 2000} value={comment} onChange={(event) => setComment(event.target.value)} required={type?.requiresComment} placeholder="Опишите детали заявки" /></label>{type?.allowsAttachments && <FilePicker label="Вложения" value={files} onChange={setFiles} multiple accept="application/pdf,image/jpeg,image/png,image/webp" maxFiles={Math.max(0, 5 - (request?.attachments.length ?? 0))} maxBytes={10 * 1024 * 1024} disabled={busy} hint="До 5 файлов на заявку, каждый не больше 10 МБ. PDF, JPEG, PNG или WebP."/>}{request && request.attachments.length > 0 && <p className="request-form-note">Вложений сейчас: {request.attachments.length}. Удалить существующие можно в карточке заявки.</p>}{error && <p className="form-inline-error" role="alert">{error}</p>}<footer><button type="button" className="app-secondary" disabled={busy} onClick={onClose}>Отмена</button><button className="app-primary" disabled={busy || !type}>{busy ? 'Сохраняем…' : type?.systemCode === 'SICK' ? request ? 'Сохранить сообщение' : 'Сообщить об отсутствии' : request ? 'Сохранить изменения' : 'Отправить заявку'}</button></footer></form></DocumentDialog>
}

function RequestAttachments({ attachments, canRemove, organizationId, requestId }: { attachments: StaffRequest['attachments']; canRemove: boolean; organizationId: string; requestId: string }) {
  const { apiRequest, downloadFile, previewFile } = useAuth()
  const queryClient = useQueryClient()
  const [preview, setPreview] = useState<{ id: string; url: string; mimeType: string } | null>(null)
  const [loadingId, setLoadingId] = useState<string | null>(null)
  const [error, setError] = useState('')
  useToastFeedback('', error)
  const [confirmId, setConfirmId] = useState<string | null>(null)
  const [removingId, setRemovingId] = useState<string | null>(null)
  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview.url) }, [preview])
  async function open(attachment: StaffRequest['attachments'][number]) {
    setLoadingId(attachment.id); setError('')
    try {
      const blob = await previewFile(attachment.downloadUrl.replace('/api', ''))
      setPreview({ id: attachment.id, url: URL.createObjectURL(blob), mimeType: attachment.mimeType })
    } catch (failure) { setError(failure instanceof Error ? failure.message : 'Не удалось открыть файл.') }
    finally { setLoadingId(null) }
  }
  async function remove(attachment: StaffRequest['attachments'][number]) {
    if (confirmId !== attachment.id) { setConfirmId(attachment.id); return }
    setRemovingId(attachment.id); setError('')
    try {
      await apiRequest(attachment.downloadUrl.replace('/api', ''), { method: 'DELETE' })
      if (preview?.id === attachment.id) setPreview(null)
      await queryClient.invalidateQueries({ queryKey: ['request', organizationId, requestId] })
    } catch (failure) { setError(failure instanceof Error ? failure.message : 'Не удалось удалить вложение.') }
    finally { setRemovingId(null); setConfirmId(null) }
  }
  return <section className="request-detail-block"><h3>Вложения</h3><div className="request-attachments">{attachments.map((attachment) => <div className="request-attachment" key={attachment.id}><div><strong>{attachment.fileName}</strong><small>{sizeLabel(attachment.size)}</small></div><button type="button" disabled={loadingId === attachment.id} onClick={() => void open(attachment)}>{loadingId === attachment.id ? 'Открываем…' : 'Посмотреть'}</button><button type="button" onClick={() => void downloadFile(attachment.downloadUrl.replace('/api', ''), attachment.fileName)}>Скачать</button>{canRemove && <button type="button" disabled={removingId === attachment.id} onClick={() => void remove(attachment)}>{removingId === attachment.id ? 'Удаляем…' : confirmId === attachment.id ? 'Подтвердить' : 'Удалить'}</button>}</div>)}</div>{error && <p className="form-inline-error" role="alert">{error}</p>}{preview && <div className="request-preview"><div><strong>{attachments.find((item) => item.id === preview.id)?.fileName}</strong><button type="button" onClick={() => setPreview(null)} aria-label="Закрыть просмотр">×</button></div>{preview.mimeType === 'application/pdf' ? <iframe title="Просмотр PDF" src={preview.url} /> : <img src={preview.url} alt="Предпросмотр вложения" />}</div>}</section>
}

export function RequestDrawer({ organization, requestId, scope, onEdit, onClose }: { organization: OrganizationSummary; requestId: string; scope: 'mine' | 'incoming' | 'history' | 'staffing'; onEdit: (request: StaffRequest) => void; onClose: () => void }) {
  const toast = useToast()
  const { apiRequest, user } = useAuth()
  const queryClient = useQueryClient()
  const detail = useRequestDetail(organization.id, requestId)
  const [comment, setComment] = useState('')
  const [reviewOpen, setReviewOpen] = useState(false)
  const [reviewKind, setReviewKind] = useState<'approve' | 'reject'>('approve')
  const [cancelOpen, setCancelOpen] = useState(false)
  const [confirmConflicts, setConfirmConflicts] = useState(false)
  const [acknowledgeWorkload, setAcknowledgeWorkload] = useState(false)
  const [absenceWarning, setAbsenceWarning] = useState(false)
  const [acknowledgeAbsence, setAcknowledgeAbsence] = useState(false)
  const [workloadWarning, setWorkloadWarning] = useState(false)
  const [error, setError] = useState('')
  useToastFeedback('', error)
  const request = detail.data?.request
  const conflicts = detail.data?.conflicts ?? []
  const reviewer = canAccess(organization, 'requests.view')
  const own = request?.isOwn ?? request?.creatorEmail === user?.email
  useEffect(() => { if (detail.data && reviewer && scope === 'incoming') void queryClient.invalidateQueries({ queryKey: ['requests', organization.id] }) }, [detail.data, organization.id, queryClient, reviewer, scope])
  const refresh = () => invalidateOrganizationWork(queryClient, organization.id)
  const decision = useMutation({ mutationFn: (kind: 'approve' | 'reject') => apiRequest<RequestMutationResponse>(`/organizations/${organization.id}/requests/${requestId}/${kind}`, { method: 'POST', body: kind === 'approve' ? { comment: comment || null, cancelConflictingShifts: confirmConflicts, acknowledgeWorkload, acknowledgeAbsence } : { comment } }), onSuccess: async (_result, kind) => { toast(_result.request.status==='PENDING'?'Этап согласован. Обращение передано дальше.':kind === 'approve' ? 'Заявка одобрена' : 'Заявка отклонена', 'success'); setReviewOpen(false); await refresh() }, onError: (failure) => { if ((failure as { code?: string }).code === 'EMPLOYEE_ABSENT') setAbsenceWarning(true); if ((failure as { code?: string }).code === 'WORKLOAD_WARNING') setWorkloadWarning(true); setError(failure instanceof Error ? failure.message : 'Не удалось обработать заявку.') } })
  const respond = useMutation({ mutationFn: () => apiRequest(`/organizations/${organization.id}/requests/${requestId}/respond`, { method: 'POST', body: { comment } }), onSuccess: async () => { toast('Отклик отправлен. Подтверждение придёт в уведомлениях.'); await refresh() }, onError: (failure) => setError(failure.message) })
  const cancel = useMutation({ mutationFn: () => apiRequest(`/organizations/${organization.id}/requests/${requestId}/cancel`, { method: 'POST', body: {} }), onSuccess: async () => { toast('Заявка отменена', 'success'); setCancelOpen(false); await refresh() }, onError: (failure) => setError(failure instanceof Error ? failure.message : 'Не удалось отменить заявку.') })
  return <DocumentDialog className="request-detail-dialog" title="Заявка" eyebrow="Заявки" onClose={onClose} headerContent={request ? <></> : undefined}>{detail.isLoading ? <div className="app-state"><span className="app-spinner" /></div> : detail.isError || !request ? <div className="app-state"><p>Не удалось открыть заявку.</p><button className="app-secondary" onClick={() => void detail.refetch()}>Повторить</button></div> : <><header><div><p className="app-eyebrow">Заявка</p><h2>Заявка · {request.typeNameSnapshot}</h2><span className={`request-status request-status--${request.status.toLowerCase()}`}>{requestStatusLabel(request)}</span></div><button aria-label="Закрыть" onClick={onClose}>×</button></header><div className="request-summary-card"><section className="request-detail-person"><MemberAvatar memberId={request.createdByMemberId} locationId={request.locationId} url={request.creatorAvatarUrl} name={request.creatorName} className="app-avatar" /><div><MemberProfileLink memberId={request.createdByMemberId} locationId={request.locationId}><strong>{request.creatorName}</strong></MemberProfileLink><span><RoleBadge role={request.creatorRole} name={request.creatorRoleName} /> · {request.creatorEmail}</span><span className="request-type-label"><RequestIcon code={request.systemCodeSnapshot} />{request.typeNameSnapshot}</span>{request.startDate && <span className="request-summary-period">{periodLabel(request)} · {absenceDays(request.startDate, request.endDate ?? request.startDate)} дн.</span>}</div></section><dl className="request-detail-grid"><div><dt>Отправлена</dt><dd>{new Date(request.createdAt).toLocaleString('ru-RU')}</dd></div><div><dt>Просмотрена</dt><dd>{request.firstReadAt ? new Date(request.firstReadAt).toLocaleString('ru-RU') : 'Ещё не просмотрена'}</dd></div>{request.resolvedByName && <div><dt>Решение принял</dt><dd>{request.resolvedByMemberId ? <MemberProfileLink memberId={request.resolvedByMemberId} locationId={request.locationId}>{request.resolvedByName}</MemberProfileLink> : request.resolvedByName}</dd></div>}</dl></div><div className={`request-detail-layout${request.status !== 'PENDING' && request.systemCodeSnapshot !== 'SICK' ? ' request-detail-layout--closed' : ''}`}><div className="request-detail-main">{request.systemCodeSnapshot === 'SICK_LEAVE' && request.status === 'PENDING' && <p className="absence-note">Старая заявка на больничный. Теперь болезнь сообщается без согласования через «Сообщить об отсутствии». Эту заявку можно отменить; её история сохранится.</p>}{request.systemCodeSnapshot === 'SICK' && request.absenceReason && <section className="request-detail-block"><h3>Причина отсутствия</h3><p>{absenceReasonLabels[request.absenceReason]}</p><p>Сообщение зарегистрировано без согласования.</p></section>}<RequestOperations organization={organization} request={request} onEdit={()=>onEdit(request)}/>{request.comment && <section className="request-detail-block"><h3>Комментарий</h3><p>{request.comment}</p></section>}{(request.relatedShiftId || ['SHIFT_PROPOSAL', 'STAFFING', 'STAFFING_RESPONSE'].includes(request.systemCodeSnapshot ?? '')) && <section className="request-detail-block"><h3>{['STAFFING', 'STAFFING_RESPONSE'].includes(request.systemCodeSnapshot ?? '') ? `Подмена · ${request.staffingPositionName}` : request.systemCodeSnapshot === 'DAY_OFF' ? 'Смена для отгула' : request.systemCodeSnapshot === 'SHIFT_PROPOSAL' ? 'Предлагаемая смена' : 'Исходная смена → Запрошенное изменение'}</h3>{request.originalStartAt && request.originalEndAt && <p className="request-shift-original"><strong>Исходная смена</strong><br /> {shiftWindow(request.originalStartAt, request.originalEndAt, organization.timezone)}</p>}{request.systemCodeSnapshot !== 'DAY_OFF' && (request.proposedStartAt && request.proposedEndAt ? <p className="request-shift-requested"><strong>Запрошенное время</strong><br /> {shiftWindow(request.proposedStartAt, request.proposedEndAt, organization.timezone)}</p> : <p>В этой заявке не указано новое время. Для переноса подайте новую заявку.</p>)}{request.relatedShiftId && <Link className="request-related-shift" to={`/app/organizations/${organization.id}/schedule?location=${request.locationId ?? organization.locationId ?? ''}&month=${zonedDateAndTime((request.status === 'APPROVED' ? request.proposedStartAt : request.originalStartAt) ?? request.createdAt, organization.timezone).date.slice(0, 7)}&shift=${request.relatedShiftId}&returnRequest=${request.id}&returnTab=${scope}`}>Открыть смену в календаре</Link>}</section>}{request.attachments.length > 0 && <RequestAttachments attachments={request.attachments} canRemove={Boolean(own && scope === 'mine' && request.status === 'PENDING')} organizationId={organization.id} requestId={requestId} />}{!!detail.data?.absenceConflicts?.length && <section className="request-conflicts"><h3>Пересечение с другим отсутствием</h3><p>В эти даты уже зарегистрировано отсутствие. Перед одобрением скорректируйте период заявки или существующее отсутствие.</p>{detail.data.absenceConflicts.map(item => <Link key={item.id} to={`/app/organizations/${organization.id}/schedule?location=${request.locationId ?? organization.locationId ?? ''}&absences=1&absence=${item.id}`}>{absenceNames[item.type]} · {displayDate(item.startDate)} — {displayDate(item.endDate)}</Link>)}</section>}{!!detail.data?.otherAbsentEmployees && <p className="absence-note">Других сотрудников с отсутствием в этом периоде: {detail.data.otherAbsentEmployees}</p>}{conflicts.length > 0 && <section className="request-conflicts"><h3>Смены в период отсутствия</h3><p>В периоде назначено смен: {conflicts.length}. {request.status === 'PENDING' ? 'При одобрении они останутся в расписании, если вы явно не подтвердите отмену.' : 'Назначенные смены можно проверить и изменить в расписании.'}</p>{conflicts.map((shift) => <div key={shift.id}><Link to={`/app/organizations/${organization.id}/schedule?location=${shift.locationId ?? request.locationId ?? organization.locationId ?? ''}&month=${zonedDateAndTime(shift.scheduledStartAt, organization.timezone).date.slice(0,7)}&shift=${shift.id}&returnRequest=${request.id}&returnTab=${scope}`}><strong>{displayDate(zonedDateAndTime(shift.scheduledStartAt, organization.timezone).date)}</strong><span>{formatTime(shift.scheduledStartAt, organization.timezone)}–{formatTime(shift.scheduledEndAt, organization.timezone)}</span></Link></div>)}</section>}{request.systemCodeSnapshot === 'STAFFING' && <section className="request-detail-block"><h3>Отклики</h3>{detail.data?.viewerCanRespond && <><label><span>Комментарий к отклику · необязательно</span><textarea rows={2} value={comment} maxLength={2000} onChange={event => setComment(event.target.value)} /></label><button className="app-primary" disabled={respond.isPending} onClick={() => respond.mutate()}>Могу выйти на подмену</button></>}{detail.data?.viewerResponseId && <Link className="app-secondary" to={`?location=${request.locationId}&tab=mine&request=${detail.data.viewerResponseId}`}>Мой отклик</Link>}{detail.data?.staffingResponses?.map(response => <Link className="staffing-response" key={response.id} to={`?location=${request.locationId}&tab=incoming&request=${response.id}`}><Avatar url={response.creatorAvatarUrl} name={response.creatorName} className="app-avatar" /><span>{response.creatorName}<small>{requestStatusLabel(response)}</small></span></Link>)}{!detail.data?.viewerCanRespond && !detail.data?.viewerResponseId && !detail.data?.staffingResponses?.length && <p>{request.status === 'PENDING' ? 'Откликов пока нет. Заявка доступна сотрудникам других точек.' : 'Заявка закрыта.'}</p>}</section>}{request.resolutionComment && <section className="request-detail-block"><h3>{request.status === 'REJECTED' ? 'Причина отклонения' : 'Комментарий к решению'}</h3><p>{request.resolutionComment}</p></section>}<section className="request-timeline"><h3>Ход заявки</h3>{request.events.map((event) => <div key={event.id}><i /><p><strong>{eventLabels[event.type]}</strong><span><MemberProfileLink memberId={event.actorMemberId} locationId={request.locationId}>{event.actorName}</MemberProfileLink> · {new Date(event.createdAt).toLocaleString('ru-RU')}</span>{event.comment && <small>{event.comment}</small>}{event.changes!=null&&<details><summary>Изменения</summary><HistoryChanges value={event.changes}/></details>}</p></div>)}</section>{error && <p className="form-inline-error">{error}</p>}</div>{(request.status === 'PENDING' || request.systemCodeSnapshot === 'SICK') && <aside className="request-detail-actions"><h3>Действия</h3>{request.status === 'PENDING' && request.canReview && canAccess(organization,request.systemCodeSnapshot==='VACATION'?'vacations.resolve':['STAFFING','STAFFING_RESPONSE'].includes(request.systemCodeSnapshot??'')?'staffing.resolve':'requests.resolve') && scope === 'incoming' && <button className="app-primary" onClick={() => setReviewOpen(true)}><RequestIcon />Рассмотреть заявку</button>}{request.status === 'PENDING' && own && reviewer && scope === 'mine' && <Link className="request-related-shift" to={`?tab=incoming&request=${request.id}`}>Открыть во вкладке «На рассмотрении»</Link>}{(request.status === 'PENDING' || (request.systemCodeSnapshot === 'SICK' && ['REGISTERED','APPROVED'].includes(request.status))) && own && canAccess(organization,'requests.edit') && <div className="request-own-actions">{!['STAFFING', 'STAFFING_RESPONSE'].includes(request.systemCodeSnapshot ?? '') && <button className="app-secondary" onClick={() => onEdit(request)}>Изменить заявку</button>}<button className="request-cancel" disabled={cancel.isPending} onClick={() => setCancelOpen(true)}>Отменить заявку</button></div>}{!(request.status === 'PENDING' || (request.systemCodeSnapshot === 'SICK' && ['REGISTERED','APPROVED'].includes(request.status))) && <p>Заявка закрыта. Решение и история сохранены.</p>}</aside>}</div>{reviewOpen && <AnimatedOverlay variant="modal" dismissible={!decision.isPending} onClose={() => setReviewOpen(false)}>{close => <DocumentDialog title="Рассмотреть заявку" className="request-review-dialog" eyebrow="Заявки" busy={decision.isPending} onClose={close} onEscape={close}><div className="request-review-person"><MemberAvatar memberId={request.createdByMemberId} locationId={request.locationId} url={request.creatorAvatarUrl} name={request.creatorName} className="app-avatar" /><span><MemberProfileLink memberId={request.createdByMemberId} locationId={request.locationId}><strong>{request.creatorName}</strong></MemberProfileLink><small>{request.typeNameSnapshot} · {periodLabel(request)}</small></span></div><section className="request-review">{absenceWarning && <label className="request-review__confirm"><input type="checkbox" checked={acknowledgeAbsence} onChange={event => setAcknowledgeAbsence(event.target.checked)} /><span>Подтверждаю назначение смены в период отсутствия</span></label>}{workloadWarning && <label className="request-review__confirm"><input type="checkbox" checked={acknowledgeWorkload} onChange={event => setAcknowledgeWorkload(event.target.checked)} /><span>Подтверждаю превышение месячной нормы</span></label>}<label><span>Комментарий к решению</span><textarea rows={3} value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Для отклонения причина обязательна" /></label>{conflicts.length > 0 && <label className="request-review__confirm"><input type="checkbox" checked={confirmConflicts} onChange={(event) => setConfirmConflicts(event.target.checked)} /><span>Отменить пересекающиеся будущие смены при одобрении</span></label>}<fieldset className="request-decision-choice"><legend>Ваше решение</legend><label><input type="radio" name="request-decision" checked={reviewKind === 'approve'} onChange={() => setReviewKind('approve')} disabled={decision.isPending || (request.systemCodeSnapshot === 'SHIFT_CHANGE' && !request.proposedStartAt) || request.systemCodeSnapshot === 'SICK_LEAVE' || request.systemCodeSnapshot === 'STAFFING'} />Одобрить</label><label><input type="radio" name="request-decision" checked={reviewKind === 'reject'} onChange={() => setReviewKind('reject')} disabled={decision.isPending} />Отклонить</label></fieldset><div><button className="app-secondary" disabled={decision.isPending} onClick={close}>Назад</button><button className={reviewKind === 'reject' ? 'app-danger' : 'app-primary'} disabled={decision.isPending || (reviewKind === 'reject' ? comment.trim().length < 3 : (request.systemCodeSnapshot === 'SHIFT_CHANGE' && !request.proposedStartAt) || request.systemCodeSnapshot === 'SICK_LEAVE' || request.systemCodeSnapshot === 'STAFFING')} onClick={() => decision.mutate(reviewKind)}>{decision.isPending ? 'Сохраняем…' : 'Сохранить решение'}</button></div>{error && <p className="form-inline-error" role="alert">{error}</p>}</section></DocumentDialog>}</AnimatedOverlay>}{cancelOpen && <AnimatedOverlay variant="modal" dismissible={!cancel.isPending} onClose={() => setCancelOpen(false)}>{close => <DocumentDialog title="Отменить заявку" className="request-cancel-dialog" busy={cancel.isPending} eyebrow="Заявки" onClose={close} onEscape={close}><p>Отменить эту заявку? Она останется в истории. Связанное отсутствие будет обновлено по действующим правилам.</p>{error && <p className="form-inline-error">{error}</p>}<footer><button className="app-secondary" disabled={cancel.isPending} onClick={close}>Назад</button><button className="app-danger" disabled={cancel.isPending} onClick={() => cancel.mutate()}>Отменить заявку</button></footer></DocumentDialog>}</AnimatedOverlay>}</>}</DocumentDialog>
}

export default function RequestsPage({ organization }: { organization: OrganizationSummary }) {
  const [params] = useSearchParams()
  const sections = requestSections(organization)
  const selected = sections.find(section => section.id === params.get('tab'))?.id ?? sections[0]?.id ?? 'mine'
  if (selected === 'vacations') return <RequestsWorkspace organization={organization} section="vacations"><VacationPlanning organization={organization}/></RequestsWorkspace>
  if (selected === 'offers') return <RequestsWorkspace organization={organization} section="offers"><RequestOffers organization={organization}/></RequestsWorkspace>
  return <RequestListPage organization={organization}/>
}

function RequestListPage({ organization }: { organization: OrganizationSummary }) {
  const reviewer = canAccess(organization, 'requests.view')
  const ownRequests = canAccess(organization,'requests.own'), staffingAccess = canAccess(organization,'staffing.respond') || canAccess(organization,'staffing.create')
  const defaultScope = ownRequests ? 'mine' : reviewer ? 'incoming' : 'staffing'
  const types = useRequestTypes(organization.id)
  const [params, setParams] = useSearchParams()
  const initialScope = params.get('tab')
  const [scope, setScope] = useState<'mine' | 'incoming' | 'history' | 'staffing'>(initialScope === 'staffing' && staffingAccess ? 'staffing' : reviewer && (initialScope === 'incoming' || initialScope === 'history') ? initialScope : initialScope === 'mine' && ownRequests ? 'mine' : defaultScope)
  const points = useLocations(organization.id)
  const [pointId, setPointId] = useState(params.get('pointId') ?? (params.get('tab') === 'staffing' ? 'all' : organization.locationId ?? ''))
  const members = useOrganizationDirectory(organization.id, reviewer)
  const filterMembers = members.data?.members.filter(member => member.locations.some(point => pointId === 'all' || !pointId || point.locationId === pointId)) ?? []
  const [memberId, setMemberId] = useState('')
  const [from, setFrom] = useState(''), [to, setTo] = useState('')
  const [page, setPage] = useState(1)
  const [extraFilters, setExtraFilters] = useState(false)
  const [typeId, setTypeId] = useState('')
  const [role, setRole] = useState('')
  const accessRoles=useAccessRoles(organization.id)
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [status, setStatus] = useState<RequestStatus | ''>('')
  const [creating, setCreating] = useState(Boolean(params.get('changeShift') || params.get('proposeShift') || params.get('dayOffShift') || params.get('reportAbsence') || params.get('staffing')))
  const [editingRequest, setEditingRequest] = useState<StaffRequest | null>(null)
  const selectedId = params.get('request')
  useLayoutEffect(() => { if (initialScope === 'absences') setParams(current => { const next = new URLSearchParams(current); next.set('tab', 'mine'); return next }, { replace: true }) }, [initialScope, setParams])
  useLayoutEffect(() => { if (initialScope === 'staffing' && staffingAccess) setScope('staffing'); else if (reviewer && (initialScope === 'incoming' || initialScope === 'history')) setScope(initialScope); else setScope(initialScope === 'mine' && ownRequests ? 'mine' : defaultScope) }, [initialScope, reviewer, staffingAccess, ownRequests, defaultScope])
  useEffect(() => { const timer = window.setTimeout(() => { setDebouncedSearch(search.trim()); setPage(1) }, 250); return () => window.clearTimeout(timer) }, [search])
  useLayoutEffect(() => { setPage(1); setMemberId(''); setPointId(initialScope === 'staffing' ? 'all' : organization.locationId ?? '') }, [initialScope, organization.locationId])
  const list = useRequests(organization.id, scope, { page, pointId: pointId || undefined, memberId: memberId || undefined, from: from || undefined, to: to || undefined, status: scope === 'incoming' ? undefined : status || undefined, typeId: typeId || undefined, role:scope==='mine'||!['OWNER','ADMIN','MEMBER'].includes(role)?undefined:role as OrganizationRole,roleId:scope==='mine'||['OWNER','ADMIN','MEMBER'].includes(role)?undefined:role||undefined, search: scope === 'mine' ? undefined : debouncedSearch || undefined })
    function openRequest(id: string) { const request = list.data?.requests.find(item => item.id === id); setParams((current) => { const result = new URLSearchParams(current); result.set('tab', scope); result.set('request', id); if (request?.locationId) result.set('location', request.locationId); return result }) }
  function closeRequest() { setParams((current) => { const result = new URLSearchParams(current); result.delete('request'); return result }, { replace: true }) }

  return <RequestsWorkspace organization={organization} section={scope} actions={(scope === 'mine' && canAccess(organization,'requests.create') && (organization.assignedToLocation !== false || organization.owner) || scope === 'staffing' && canAccess(organization,'staffing.create')) && <button className="app-primary" onClick={() => { if (scope === 'staffing') setParams(current => { const next = new URLSearchParams(current); next.set('staffing', '1'); return next }); setCreating(true) }}><span aria-hidden="true">＋</span> Создать заявку</button>}><div className="request-list-toolbar"><span>{list.data ? `${list.data.pagination.total} заявок` : 'Заявки'}</span><button className="app-secondary" aria-expanded={extraFilters} onClick={() => setExtraFilters(true)}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden="true"><path d="M4 6h16M7 12h10M10 18h4" /></svg>Фильтры{[from,to,memberId,role,typeId,status,search].filter(Boolean).length > 0 && <small>{[from,to,memberId,role,typeId,status,search].filter(Boolean).length}</small>}</button></div>{extraFilters && <AnimatedOverlay variant="modal" onClose={() => setExtraFilters(false)}>{close => <DocumentDialog title="Фильтры" className="request-filters-dialog" eyebrow="Заявки" onClose={close}><div className="request-filter-dialog-fields"><label><span>Точка</span><Select value={pointId} onChange={event => { setPointId(event.target.value); setMemberId(''); setPage(1) }}><option value="all">{scope === 'mine' || scope === 'staffing' ? 'Все точки' : 'Все управляемые точки'}</option>{points.data?.locations.filter(point => !point.archivedAt && (scope === 'mine' || scope === 'staffing' || point.permissions?.includes('requests.view'))).map(point => <option key={point.id} value={point.id}>{point.name}</option>)}</Select></label><label><span>Тип заявки</span><Select value={typeId} onChange={(event) => { setTypeId(event.target.value); setPage(1) }}><option value="">Все типы</option>{types.data?.types.map((type) => <option value={type.id} key={type.id}>{type.name}</option>)}</Select></label>{scope !== 'incoming' && <label><span>Статус</span><Select value={status} onChange={(event) => { setStatus(event.target.value as RequestStatus | ''); setPage(1) }}><option value="">Все статусы</option>{Object.entries(statusLabels).filter(([value]) => scope === 'mine' || scope === 'staffing' || value !== 'PENDING').map(([value, label]) => <option value={value} key={value}>{label}</option>)}</Select></label>}{reviewer && !['mine', 'staffing'].includes(scope) && <><label className="requests-search"><span>Поиск заявки</span><input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Имя, фамилия или почта" autoComplete="off" /></label></>}{reviewer && !['mine','staffing'].includes(scope) && <><label className="request-extra-filter"><span>Роль автора</span><Select value={role} onChange={(event) => { setRole(event.target.value); setPage(1) }}><option value="">Все роли</option><option value="OWNER">Владелец</option>{accessRoles.data?.roles.filter(r=>r.systemCode!=='OWNER').map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</Select></label><div className="request-extra-filter"><EmployeePicker members={filterMembers} value={memberId} onChange={value => { setMemberId(value); setPage(1) }} required={false} emptyLabel="Все сотрудники" /></div></>}<label className="request-extra-filter"><span>Период с</span><DatePicker value={from} onChange={event => { setFrom(event.target.value); setPage(1) }} /></label><label className="request-extra-filter"><span>По</span><DatePicker min={from} value={to} onChange={event => { setTo(event.target.value); setPage(1) }} /></label></div><footer><button className="app-secondary" onClick={() => { setFrom(''); setTo(''); setMemberId(''); setRole(''); setTypeId(''); setStatus(''); setSearch(''); setPage(1) }}>Сбросить</button><button className="app-primary" onClick={close}>Готово</button></footer></DocumentDialog>}</AnimatedOverlay>}<AsyncPanel pending={list.isLoading} identity={`${scope}:${page}:${pointId}:${memberId}:${from}:${to}:${status}:${typeId}:${role}:${debouncedSearch}`} minHeight={320}>{list.isLoading ? <div className="app-state"><span className="app-spinner" />Загружаем заявки…</div> : list.isError ? <div className="app-state"><p>Не удалось загрузить заявки.</p><button className="app-secondary" onClick={() => void list.refetch()}>Повторить</button></div> : !list.data?.requests.length ? <div className="requests-empty"><h2>{scope === 'staffing' ? 'Открытых подмен пока нет' : scope === 'mine' ? 'У вас пока нет заявок' : scope === 'incoming' ? 'Нет заявок для рассмотрения' : 'В архиве пока пусто'}</h2><p>{scope === 'staffing' ? 'Здесь появятся заявки точек, которым нужны сотрудники на смену.' : scope === 'mine' ? 'Создайте заявку, когда потребуется отпуск, отгул или изменение смены.' : scope === 'incoming' ? 'Новые заявки участников организации появятся здесь, в том числе ваши.' : 'Здесь появятся решённые и отменённые заявки организации.'}</p></div> : <div className="requests-list"><div className="request-table-header" aria-hidden="true"><span>Сотрудник</span><span>Тип / точка</span><span>Период</span><span>Дней</span><span>Статус</span><span>Дата подачи</span><span /></div>{list.data.requests.map((request) => <RequestCard key={request.id} request={request} incoming={scope !== 'mine'} timezone={organization.timezone} onOpen={() => openRequest(request.id)} />)}</div>}{list.data && <nav className="members-pagination"><button className="app-secondary" disabled={page === 1} onClick={() => setPage((value) => value - 1)}>Назад</button><span>Показано {list.data.requests.length} из {list.data.pagination.total} · Страница {page} из {Math.max(1, list.data.pagination.pages)}</span><button className="app-secondary" disabled={page >= list.data.pagination.pages} onClick={() => setPage((value) => value + 1)}>Далее</button></nav>}</AsyncPanel>{creating && <AnimatedOverlay variant="modal" onClose={() => setCreating(false)}>{(close) => <RequestForm organization={organization} initialSystemCode={params.has('staffing') || scope === 'staffing' ? 'STAFFING' : params.has('dayOffShift') ? 'DAY_OFF' : params.has('reportAbsence') ? 'SICK' : undefined} initialShiftId={params.get('changeShift') ?? params.get('dayOffShift') ?? undefined} initialProposal={params.has('proposeShift')} initialProposalDate={params.get('proposalDate') ?? undefined} onClose={() => { setParams(current => { const next = new URLSearchParams(current); next.delete('staffing'); next.delete('dayOffShift'); next.delete('reportAbsence'); next.delete('changeShift'); next.delete('proposeShift'); next.delete('proposalDate'); return next }, { replace: true }); close() }} />}</AnimatedOverlay>}{editingRequest && <AnimatedOverlay variant="modal" onClose={() => setEditingRequest(null)}>{(close) => <RequestForm organization={organization} request={editingRequest} onClose={close} />}</AnimatedOverlay>}{selectedId && <AnimatedOverlay variant="modal" onClose={closeRequest}>{() => <RequestDrawer organization={organization} requestId={selectedId} scope={scope} onEdit={(item) => { closeRequest(); setEditingRequest(item) }} onClose={closeRequest} />}</AnimatedOverlay>}</RequestsWorkspace>
}

function HistoryChanges({value}:{value:unknown}){const change=value as {before?:Record<string,unknown>;after?:Record<string,unknown>;automatic?:boolean;employeeConsent?:boolean};const names:Record<string,string>={startDate:'Первый день',endDate:'Последний день',comment:'Комментарий',reason:'Причина',proposedStartAt:'Начало смены',proposedEndAt:'Окончание смены',cancelled:'Отмена'};return <div>{Object.entries(names).filter(([k])=>change.before?.[k]!==change.after?.[k]&&(change.before?.[k]!==undefined||change.after?.[k]!==undefined)).map(([k,label])=><p key={k}>{label}: {String(change.before?.[k]??'—')} → {String(change.after?.[k]??'—')}</p>)}{change.employeeConsent&&<p>Согласие сотрудника зафиксировано.</p>}{change.automatic&&<p>Действие выполнено системой.</p>}</div>}
